cd /private/var/folders/kp/vdv61pd97vd0x29b257r8h7h0000gn/T/opencode/barcode_analysis && python3 << 'EOF'
import urllib.request, json, re, time

slugs = {}
n_total = None
for start in range(0, 2200, 50):
    url = f"https://moviebarcode.tumblr.com/api/read/json?num=50&start={start}"
    for attempt in range(3):
        try:
            raw = urllib.request.urlopen(url, timeout=30).read().decode('utf-8', 'replace')
            break
        except Exception as e:
            time.sleep(2)
    else:
        print("FAILED", start); continue
    raw = raw.strip()
    if raw.startswith("var tumblr_api_read = "):
        raw = raw[len("var tumblr_api_read = "):]
    raw = raw.rstrip(';')
    try:
        data = json.loads(raw)
    except Exception as e:
        print("parse fail", start, e); continue
    n_total = data.get("posts-total")
    for p in data.get("posts", []):
        slugs[p["id"]] = (p.get("slug",""), p.get("date-gmt",""))
    if start % 400 == 0:
        print("...", start)
    time.sleep(0.15)

print("total posts:", len(slugs), "posts-total:", n_total)
with open("slugs.json","w") as f:
    json.dump(slugs, f)

keys = ["day-of-the-dead","exorcist","apollo-18","villains","stonehearst","nosferatu","wish-upon","silent-house","automata","boogeyman"]
for k in keys:
    hits = [(s,d) for s,d in slugs.values() if k in s.lower()]
    print(f"== {k}: {len(hits)}")
    for s,d in hits[:12]:
        print("   ", d[:10], s)
EOF

