cd /private/var/folders/kp/vdv61pd97vd0x29b257r8h7h0000gn/T/opencode/barcode_analysis && python3 << 'EOF'
import urllib.request, urllib.parse, re

def tmdb_search(q):
    url = "https://www.themoviedb.org/search?query=" + urllib.parse.quote(q)
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)'})
    html = urllib.request.urlopen(req, timeout=30).read().decode('utf-8','replace')
    # movie cards link to /movie/<id>-<slug>
    hits = re.findall(r'/movie/(\d+)-([a-z0-9-]+)', html)
    seen=[]
    for h in hits:
        if h not in seen: seen.append(h)
    return seen[:8], len(html)

for q in ["Day of the Dead 1985", "Apollo 18 2011", "Silent House 2011"]:
    hits, n = tmdb_search(q)
    print(q, "html_len", n, "hits:", hits)
EOF

