import urllib.request, urllib.parse, json, time

UA = {'User-Agent':'barcode-id-research/1.0 (contact: none) python-urllib'}

def wd(q, tries=4):
    url = "https://www.wikidata.org/w/api.php?" + q
    for t in range(tries):
        try:
            req = urllib.request.Request(url, headers=UA)
            return json.load(urllib.request.urlopen(req, timeout=30))
        except Exception as e:
            print("  retry", t, e); time.sleep(8*(t+1))
    return None

films = {
 'day_of_dead': 'Day of the Dead (1985 film)',
 'exorcist3': 'The Exorcist III',
 'apollo18': 'Apollo 18 (film)',
 'villains': 'Villains (2019 film)',
 'stonehearst': 'Stonehearst Asylum',
 'nosferatu': 'Nosferatu the Vampyre',
 'wishupon': 'Wish Upon',
 'silenthouse': 'Silent House (film)',
 'automata': 'Automata (film)',
 'boogeyman': 'Boogeyman (film)',
}
titles = '|'.join(f'{k}={urllib.parse.quote(v)}' for k,v in films.items())
# use wbgetentities by site+title (multiple titles allowed via |)
url_q = "action=wbgetentities&format=json&sites=enwiki&props=claims&" + "&".join(f"titles={urllib.parse.quote(v)}" for v in []) 
# Actually wbgetentities accepts titles param with pipe-separated values and sites
q = "action=wbgetentities&format=json&sites=enwiki&props=claims|labels&titles=" + urllib.parse.quote("|".join(films.values()))
d = wd(q)
if d:
    ents = d.get('entities', {})
    out = {}
    for eid, e in ents.items():
        label = e.get('labels',{}).get('en',{}).get('value','?')
        c = e.get('claims', {})
        imdb = [x['mainsnak']['datavalue']['value'] for x in c.get('P345',[]) if 'datavalue' in x['mainsnak']]
        tmdb = [x['mainsnak']['datavalue']['value'] for x in c.get('P4947',[]) if 'datavalue' in x['mainsnak']]
        out[label] = {'q': eid, 'imdb': imdb, 'tmdb': tmdb}
        print(f"{label:32s} q={eid} imdb={imdb} tmdb={tmdb}")
    json.dump(out, open("wikidata.json","w"), indent=1)
else:
    print("failed")
EOF","timeout":300000}

